import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.logging.Logger;

public class AssetSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Anti-automation: basic rate check (in-memory, resets on restart)
    private final java.util.concurrent.ConcurrentHashMap<String, Long> lastRequest = 
        new java.util.concurrent.ConcurrentHashMap<>();

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, java.io.IOException {

        String clientIp = req.getHeader("X-Real-IP");
        if (clientIp == null) clientIp = req.getRemoteAddr();

        // Rate limiting: 1 request per 100ms per IP
        Long last = lastRequest.get(clientIp);
        long now = System.currentTimeMillis();
        if (last != null && (now - last) < 100) {
            resp.setStatus(429);
            resp.getWriter().write("{\"error\":\"rate limited\"}");
            return;
        }
        lastRequest.put(clientIp, now);

        String assetType = req.getParameter("type");
        String searchTerm = req.getParameter("q");
        String orgId = req.getParameter("org");

        if (searchTerm == null || searchTerm.isEmpty()) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"missing search term\"}");
            return;
        }

        // Input length check
        if (searchTerm.length() > 200) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"search term too long\"}");
            return;
        }

        // Org ID validation - must be numeric
        if (orgId != null && !orgId.matches("^[0-9]+$")) {
            resp.setStatus(400);
            resp.getWriter().write("{\"error\":\"invalid org id\"}");
            return;
        }

        // Build query - type is used to select table partition
        String table = "assets_general";
        if (assetType != null) {
            switch(assetType) {
                case "hardware": table = "assets_hardware"; break;
                case "software": table = "assets_software"; break;
                case "network": table = "assets_network"; break;
                default: table = "assets_general";
            }
        }

        // VULNERABLE: searchTerm is concatenated into SQL
        String sql = "SELECT asset_id, name, description, status FROM " + table + 
                     " WHERE org_id = " + (orgId != null ? orgId : "1") +
                     " AND (name LIKE '%" + searchTerm + "%' OR description LIKE '%" + searchTerm + "%')" +
                     " ORDER BY name LIMIT 50";

        log.info("Executing search: org=" + orgId + " type=" + assetType + " term_length=" + searchTerm.length());

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(sql)) {

            StringBuilder json = new StringBuilder("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",\n");
                json.append("  {\"id\":").append(rs.getInt("asset_id"))
                    .append(",\"name\":\"").append(escapeJson(rs.getString("name")))
                    .append("\",\"description\":\"").append(escapeJson(rs.getString("description")))
                    .append("\",\"status\":\"").append(escapeJson(rs.getString("status")))
                    .append("\"}");
                first = false;
            }
            json.append("\n]");

            resp.setContentType("application/json");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            log.warning("SQL error: " + e.getMessage());
            resp.setStatus(500);
            // Expose error detail for debugging in non-prod
            if ("true".equals(System.getenv("DEBUG_MODE"))) {
                resp.getWriter().write("{\"error\":\"" + escapeJson(e.getMessage()) + "\"}");
            } else {
                resp.getWriter().write("{\"error\":\"internal error\"}");
            }
        }
    }

    private String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r");
    }
}
